// Tree and graves. Hex because shadeColor parses it. FILLS is indexed by cell kind, see CELL in scene/overlay.ts.
const scaleHex = (hex: string, k: number) => `#${[1, 3, 5].map((at) => Math.min(255, Math.round(parseInt(hex.slice(at, at + 2), 16) * k)).toString(16).padStart(2, "0")).join("")}`;
export const GIFT_WRAP = ["#a63d50", "#3f7a4a", "#3c5a9a", "#7a4fa0"];
// Per wrap: lit top, one pair of sides, the other pair in shade, so a turning box reads as solid.
const GIFT_FACES = GIFT_WRAP.flatMap((hex) => [scaleHex(hex, 1.3), hex, scaleHex(hex, 0.65)]);
export const RIBBON_FILL = ["#c9a24a", "#b8bccb"];
