import {BLOSSOM, GOLD, GREEN, RED} from "../theme";
import {project, type Camera, type Point} from "./camera";
import {CELL, plot, type Overlay} from "./overlay";
import {clamp01, SPRING} from "./timeline";
import type {Tree} from "./tree";

// Arrays, not strings: these icons are surrogate pairs, so indexing a string would split them.
const POINTED = "\u{f06c}", ROUND = "\u{f032a}", MAPLE = "\u{f0c93}";
const FLOWER = "\u{f024a}", TULIP = "\u{f09f1}", POPPY = "\u{f0d08}";
const GLYPHS = [[POINTED, ROUND, POINTED, ROUND], [POINTED, ROUND, MAPLE, POINTED], [MAPLE, POINTED, MAPLE, ROUND], [FLOWER, TULIP, POPPY, FLOWER]];
const STAGES = [GREEN, GOLD, RED, BLOSSOM];
const STAGE_KINDS = [CELL.leaf, CELL.goldLeaf, CELL.autumnLeaf, CELL.leaf];
const BLOSSOM_STAGE = 3;
// Clusters sit forward of the wood so the crown reads as foliage rather than bare branches.
const FORWARD = 0.3;
const MIN_CLUSTER_RADIUS = 8;
// Shares of spring. Buds open over the first, then a flower lasts the second before turning green.
const BUDDING = 0.7;
const BLOOM = 0.3;

// The cells around a leaf, a diamond that widens with zoom: at 1 it is the four neighbours.
const clusters: [number, number][][] = [];
export function clusterAt(reach: number) {
    clusters[ reach ] ??= Array.from({length: (2 * reach + 1) ** 2}, (_, i): [number, number] => [(i % (2 * reach + 1)) - reach, Math.floor(i / (2 * reach + 1)) - reach])
        .filter(([dx, dy]) => (dx || dy) && Math.abs(dx) + Math.abs(dy) <= reach);

    return clusters[ reach ];
}

export function drawLeaves(overlay: Overlay, camera: Camera, tree: Tree, local: number, autumn: number) {
    const p: Point = {x: 0, y: 0, z: 0};
    const clustered = camera.view.radius >= MIN_CLUSTER_RADIUS;
    const cluster = clusterAt(Math.round(camera.view.zoom));
    for (const leaf of tree.leaves) {
        const opens = leaf.bud * BUDDING * SPRING;
        if (local < opens) continue;

        // Each leaf turns, then falls, on its own schedule.
        const drop = clamp01((autumn - 0.35 - leaf.delay * 0.5) / 0.15);
        if (drop >= 1) continue;

        const sway = Math.sin(drop * 9 + leaf.drift) * 0.12 * drop;
        project(camera, leaf.at[ 0 ] + sway, Math.max(-1, leaf.at[ 1 ] - drop * drop * 2.4), leaf.at[ 2 ], p);
        const blooming = leaf.flower && local < opens + BLOOM * SPRING;
        const stage = blooming ? BLOSSOM_STAGE : Math.min(2, Math.floor(clamp01((autumn - leaf.delay * 0.35) / 0.1) * 3));
        const palette = STAGES[ stage ]!, glyphs = GLYPHS[ stage ]!, kind = STAGE_KINDS[ stage ]!;
        const z = p.z - FORWARD;
        plot(overlay, p.x, p.y, z, glyphs[ leaf.kind ]!, palette[ leaf.kind ]!, kind);
        if (!clustered || drop > 0) continue;

        for (let i = 0; i < cluster.length; i++) {
            const shape = (leaf.kind + i + 1) % glyphs.length;
            plot(overlay, p.x + cluster[ i ]![ 0 ], p.y + cluster[ i ]![ 1 ], z, glyphs[ shape ]!, palette[ shape ]!, kind);
        }
    }
}
