import {GIFT_WRAP, ORNAMENTS, PINE, RIBBON, STAR_GOLD} from "../theme";
import {project, type Camera, type Point} from "./camera";
import {clusterAt} from "./leaves";
import {emit} from "./glow";
import {CELL, plot, type Overlay} from "./overlay";
import {mulberry32} from "./random";
import {drawWood, type Segment} from "./tree";
import {drawYard, growYard, type Yard} from "./yard";

const TIERS = 8;
const BASE = -0.62, TOP = 0.62; // heights of the lowest and highest tier, ground at -1
const NEEDLES = ["\u{f0405}", "^", "\u{f0405}"];
const BAUBLE = "\u{f0765}", LIGHT = "\u{f09df}", BOW = "\u{f0678}";
const CHASE = 250; // ms per step of the colours running along the garland
const BEADS = 150, TURNS = 5;

type Vec = [x: number, y: number, z: number];

// kind: 0 needle, 1 snow on a bough, 2 bauble.
type Spot = {
    at   : Vec;
    kind : number;
    shade: number;
};

type Gift = {
    angle : number;
    reach : number;
    width : number;
    height: number;
    depth : number;
    spin  : number;
    wrap  : number;
    ribbon: number;
};

export type Pine = {
    trunk  : Segment[];
    spots  : Spot[];
    gifts  : Gift[];
    garland: Vec[];
    yard   : Yard;
};

export function growPine(seed: number): Pine {
    const random = mulberry32(seed);
    const spots: Spot[] = [];
    for (let i = 0; i < TIERS; i++) {
        const t = i / (TIERS - 1);
        const top = BASE + t * (TOP - BASE);
        const reach = 0.5 * (1 - t) + 0.08;
        // Rings from the trunk out; each droops toward its tip like a bough under snow.
        for (const s of [0.3, 0.5, 0.7, 0.85, 1]) {
            const around = Math.max(5, Math.round(40 * reach * s));
            for (let j = 0; j < around; j++) {
                const angle = ((j + random() * 0.6) / around) * Math.PI * 2 + i;
                const r = reach * s * (0.92 + random() * 0.16);
                const outer = s === 1, roll = random();
                const kind = outer && roll < 0.2 ? 2 : s < 0.9 && roll < 0.22 ? 1 : 0;
                spots.push({at: [Math.cos(angle) * r, top - 0.14 * s * s + (random() - 0.5) * 0.03, Math.sin(angle) * r], kind, shade: Math.floor(random() * 15)});
            }
        }
    }

    const gifts = Array.from({length: 7}, (_, i): Gift => ({
        angle : ((i + random() * 0.5) / 7) * Math.PI * 2,
        reach : 0.5 + random() * 0.25,
        width : 0.13 + random() * 0.09,
        height: 0.08 + random() * 0.08,
        depth : 0.1 + random() * 0.08,
        spin  : random() * Math.PI,
        wrap  : i % GIFT_WRAP.length,
        ribbon: Math.floor(random() * RIBBON.length),
    }));

    // A string of lights winding up the cone, just outside the bough tips.
    const garland = Array.from({length: BEADS}, (_, i): Vec => {
        const u = i / BEADS, y = BASE - 0.12 + u * (TOP - BASE + 0.05);
        const r = 0.5 * (1 - Math.min(1, Math.max(0, (y + 0.12 - BASE) / (TOP - BASE)))) + 0.1;
        const angle = u * TURNS * Math.PI * 2;

        return [Math.cos(angle) * r, y, Math.sin(angle) * r];
    });

    return {trunk: [{from: [0, -1, 0], to: [0, BASE, 0], depth: 0, level: 0.6}], spots, gifts, garland, yard: growYard(random)};
}

export function drawPine(overlay: Overlay, camera: Camera, pine: Pine, time: number) {
    const p: Point = {x: 0, y: 0, z: 0};
    drawWood(overlay, camera, {segments: pine.trunk, leaves: []});

    const cluster = clusterAt(Math.round(camera.view.zoom));
    const chase = Math.floor(time / CHASE);
    const glowReach = Math.max(1.5, camera.view.radius * 0.14);
    for (const {at, kind, shade} of pine.spots) {
        project(camera, at[ 0 ], at[ 1 ], at[ 2 ], p);
        if (kind === 2) {
            plot(overlay, p.x, p.y, p.z - 0.05, BAUBLE, ORNAMENTS[ shade % ORNAMENTS.length ]!, CELL.leaf);
            emit(overlay, p.x, p.y, p.z - 0.05, ORNAMENTS[ shade % ORNAMENTS.length ]!, glowReach, 0.5);
            continue;
        }

        const char = kind === 1 ? "\u{f0717}" : NEEDLES[ shade % NEEDLES.length ]!;
        const color = kind === 1 ? RIBBON[ 1 ]! : PINE[ shade % PINE.length ]!;
        plot(overlay, p.x, p.y, p.z, char, color, kind === 1 ? CELL.snow : CELL.leaf);
        for (let i = 0; i < cluster.length; i++) {
            plot(overlay, p.x + cluster[ i ]![ 0 ], p.y + cluster[ i ]![ 1 ], p.z + 0.01, NEEDLES[ (shade + i) % NEEDLES.length ]!, PINE[ (shade + i) % PINE.length ]!, CELL.leaf);
        }
    }

    pine.garland.forEach(([x, y, z], i) => {
        const color = ORNAMENTS[ (Math.floor(i / 4) + chase) % ORNAMENTS.length ]!;
        project(camera, x, y, z, p);
        plot(overlay, p.x, p.y, p.z - 0.02, LIGHT, color, CELL.leaf);
        emit(overlay, p.x, p.y, p.z - 0.02, color, glowReach * 0.7, 0.45);
    });

    project(camera, 0, TOP + 0.13, 0, p);
    drawStar(overlay, p.x, p.y, p.z - 1, Math.max(2, camera.view.radius * 0.15), camera.view.aspect);
    emit(overlay, p.x, p.y, p.z - 1, STAR_GOLD, glowReach * 2.5, 1);

    for (const gift of pine.gifts) drawGift(overlay, camera, gift, p);
    drawYard(overlay, camera, pine.yard);
}

// A five-point star always facing the camera, `size` rows from centre to tip, each point split down its middle
// into a lit and a shaded facet.
function drawStar(overlay: Overlay, x: number, y: number, z: number, size: number, aspect: number) {
    const corners = Array.from({length: 10}, (_, i) => {
        const a = Math.PI / 2 + (i * Math.PI) / 5, r = i % 2 ? size * 0.42 : size;

        return [Math.cos(a) * r, Math.sin(a) * r];
    });

    const side = (ax: number, ay: number, bx: number, by: number, px: number, py: number) => (bx - ax) * (py - ay) - (by - ay) * (px - ax);
    const across = Math.ceil(size / aspect);
    for (let row = Math.floor(y - size); row <= Math.ceil(y + size); row++) {
        for (let col = Math.floor(x - across); col <= Math.ceil(x + across); col++) {
            // Cell centre in the star's own units: rows up, columns scaled to rows.
            const px = (col - x) * aspect, py = y - row;
            for (let i = 0; i < 10; i++) {
                const [ax, ay] = corners[ i ]!, [bx, by] = corners[ (i + 1) % 10 ]!;
                const s1 = side(0, 0, ax!, ay!, px, py), s2 = side(ax!, ay!, bx!, by!, px, py), s3 = side(bx!, by!, 0, 0, px, py);
                if ((s1 < 0 || s2 < 0 || s3 < 0) && (s1 > 0 || s2 > 0 || s3 > 0)) continue;

                plot(overlay, col, row, z, " ", STAR_GOLD, CELL.star + (i % 2));
                break;
            }
        }
    }
}

// A wrapped box standing on the ground: its top and sides are sampled in the world, so the depth buffer
// keeps whichever faces turn toward the camera. A ribbon band runs round the middle of each side and crosses on top.
function drawGift(overlay: Overlay, camera: Camera, {angle, reach, width, height, depth, spin, wrap, ribbon}: Gift, p: Point) {
    const {aspect, radius} = camera.view;
    const cx = Math.cos(angle) * reach, cz = Math.sin(angle) * reach;
    const cos = Math.cos(spin), sin = Math.sin(spin);
    const step = (Math.min(aspect, 1) / Math.max(1, radius)) * 0.6;
    const band = Math.max(step, width * 0.09);
    const dot = (u: number, v: number, y: number, face: number, crossing: boolean) => {
        project(camera, cx + u * cos - v * sin, y, cz + u * sin + v * cos, p);
        plot(overlay, p.x, p.y, p.z, " ", RIBBON[ ribbon ]!, crossing ? CELL.ribbon + ribbon : CELL.gift + wrap * 3 + face);
    };

    const hw = width / 2, hd = depth / 2, ground = -1, lid = ground + height;
    for (let a = -hw; a <= hw; a += step) {
        for (let b = -hd; b <= hd; b += step) dot(a, b, lid, 0, Math.abs(a) < band || Math.abs(b) < band);
        for (let y = ground; y <= lid; y += step) {
            dot(a, -hd, y, 1, Math.abs(a) < band);
            dot(a, hd, y, 1, Math.abs(a) < band);
        }
    }
    for (let b = -hd; b <= hd; b += step) {
        for (let y = ground; y <= lid; y += step) {
            dot(-hw, b, y, 2, Math.abs(b) < band);
            dot(hw, b, y, 2, Math.abs(b) < band);
        }
    }

    project(camera, cx, lid + step, cz, p);
    plot(overlay, p.x, p.y, p.z - 0.01, BOW, RIBBON[ ribbon ]!, CELL.leaf);
}
