import type {Lang} from "../cv/data";
import {createOverlay, type Overlay} from "../scene/overlay";
import {createPiece} from "../scene/calendar";
import type {Piece} from "../scene/rasterize";
import type {Scene} from "../scene/background";
import type {Line} from "../terminal/lines";
import {createShell, resetShell, type Shell} from "../shell/shell";
import {tabs} from "../terminal/pages";

export type HitAction = {
    kind : "tab";
    index: number;
} | {
    kind: "lang";
    lang: Lang;
} | {
    kind: "url";
    url : string;
} | { kind: "shell" };

export type Hit = {
    x0    : number;
    x1    : number;
    y     : number;
    action: HitAction;
};

// All app state: created once in index.ts and passed down.
export type App = {
    lang      : Lang;
    tab       : number;
    scroll    : number;
    maxScroll : number;
    viewRows  : number;
    reduced   : boolean;
    hover     : boolean;
    hits      : Hit[];
    cellWidth : number;
    lineHeight: number;
    tiltY     : number;
    tabBar    : boolean;
    piece     : Piece;
    scene     : Scene;
    overlay   : Overlay;
    shell     : Shell;
    pageWidth : number;
    pageKey   : string;
    pageLines : Line[];
};

export const createApp = ({reduced, hover, seed, piece = null}: {
    reduced: boolean;
    hover  : boolean;
    seed   : number;
    piece? : string | null; // a piece by name, else the one the calendar picks for today
}): App => ({
    lang      : "en", tab       : 0, scroll    : 0, maxScroll : 0, viewRows  : 10,
    reduced, hover,
    tabBar    : true,
    hits      : [], cellWidth : 8, lineHeight: 16,
    tiltY     : 0,
    piece     : createPiece(piece, new Date(), seed),
    scene     : {hole: {x: 0, y: 0, w: 0, h: 0}, time: 0, horizon: 0, yaw: 0, cx: 0, base: 0, shadow: 0, brown: 0, snow: 0, aurora: false, clouds: 1},
    overlay   : createOverlay(0, 0),
    shell     : createShell(tabs[ 0 ]!.dir), pageWidth : 80,
    pageKey   : "", pageLines : [],
});

export function selectTab(app: App, index: number) {
    app.tab = (index + tabs.length) % tabs.length;
    app.scroll = 0;
    resetShell(app.shell, tabs[ app.tab ]!.dir);
}

export function scrollBy(app: App, rows: number) {
    app.scroll = Math.max(0, Math.min(app.maxScroll, app.scroll + rows));
}

export const hitAt = ({hits}: App, x: number, y: number) => hits.find((h) => h.y === y && x >= h.x0 && x < h.x1);
export const hitAtPixel = (app: App, px: number, py: number) => hitAt(app, Math.floor(px / app.cellWidth), Math.floor(py / app.lineHeight));
