import type {View} from "./camera";
import {glowPass} from "./glow";
import {lightPass} from "./lighting";
import type {Overlay} from "./overlay";
import {drawSnow} from "./snowfall";

// What stands in the middle of the field: draws itself into the overlay for one frame.
export type Piece = {
    draw   : (overlay: Overlay, view: View) => void;
    winter?: boolean; // snow on the ground and falling all the time, instead of the seasons turning
    shadow?: number; // size of the ground shadow against the oak's crown, 1 by default
    aurora?: boolean; // northern lights in the sky
    clouds?: number; // share of the usual cloud cover, 1 by default
};

// Sky, ground and seasons are shared; only the piece changes with the calendar.
export function rasterize(view: View, overlay: Overlay, piece: Piece) {
    overlay.depth.fill(Infinity);
    overlay.glow.fill(0);
    if (view.radius <= 0) return;

    piece.draw(overlay, view);
    drawSnow(overlay, view, piece.winter);
    glowPass(overlay, view.aspect);
    lightPass(overlay);
}
