import {BARK, TWIG_INK} from "../theme";
import {project, type Camera, type Point} from "./camera";
import {CELL, plot, type Overlay} from "./overlay";
import {mulberry32} from "./random";

const MAX_DEPTH = 6;
const OUTWARD = 0.5;
const FLATTEN = 0.7;
export const SCALE = 0.8;
const LEAVES_PER_TIP = 3;
const FLOWER_SHARE = 0.3;
const PIECES = 3;
const MAX_GIRTH = 5;
const TAPER = 0.6;

type Vec = [x: number, y: number, z: number];

export type Segment = {
    from : Vec;
    to   : Vec;
    depth: number;
    level: number;
};

// bud and delay are 0..1 shares of spring and autumn, so each leaf keeps its own schedule.
export type Leaf = {
    at    : Vec;
    bud   : number;
    delay : number;
    drift : number;
    kind  : number;
    flower: boolean;
};

export type Tree = {
    segments: Segment[];
    leaves  : Leaf[];
};

const normal = ([x, y, z]: Vec): Vec => {
    const len = Math.hypot(x, y, z) || 1;

    return [x / len, y / len, z / len];
};

export function growTree(seed: number): Tree {
    const random = mulberry32(seed);
    const spread = (amount: number) => (random() - 0.5) * amount;
    const segments: Segment[] = [];
    const leaves: Leaf[] = [];

    const branch = (start: Vec, heading: Vec, length: number, depth: number) => {
        let at = start;
        let dir = heading;
        for (let i = 0; i < PIECES; i++) {
            dir = normal([dir[ 0 ] + spread(0.35), dir[ 1 ] + spread(0.2) + 0.01, dir[ 2 ] + spread(0.35)]);
            const step = length / PIECES;
            const to: Vec = [at[ 0 ] + dir[ 0 ] * step, at[ 1 ] + dir[ 1 ] * step, at[ 2 ] + dir[ 2 ] * step];
            segments.push({from: at, to, depth, level: depth + i / PIECES});
            at = to;
        }
        if (depth === MAX_DEPTH) {
            for (let i = 0; i < LEAVES_PER_TIP; i++) {
                leaves.push({
                    at    : [at[ 0 ] + spread(0.16), at[ 1 ] + spread(0.1), at[ 2 ] + spread(0.16)],
                    bud   : random(),
                    delay : random(),
                    drift : random() * Math.PI * 2,
                    kind  : Math.floor(random() * 4),
                    flower: random() < FLOWER_SHARE,
                });
            }

            return;
        }

        const children = depth < 2 ? 3 : random() > 0.6 ? 3 : 2;
        for (let i = 0; i < children; i++) {
            // The first child continues the limb, so the tree keeps a leader instead of forking flat.
            const lean = i === 0 ? 0.35 : 0.9 + random() * 0.7;
            // Early limbs fan out evenly; later ones wander.
            const turn = depth < 2 ? i * 2.4 + depth + random() * 0.6 : random() * Math.PI * 2;
            // Pull away from the trunk, so limbs spread instead of curling back into the crown.
            const out = Math.hypot(at[ 0 ], at[ 2 ]) || 1;
            const next = normal([
                dir[ 0 ] + Math.cos(turn) * lean + (at[ 0 ] / out) * OUTWARD,
                dir[ 1 ] * FLATTEN + 0.1 + spread(0.2),
                dir[ 2 ] + Math.sin(turn) * lean + (at[ 2 ] / out) * OUTWARD,
            ]);

            branch(at, next, length * (0.74 + random() * 0.1), depth + 1);
        }
    };

    branch([0, 0, 0], [0, 1, 0], 0.3, 0);

    // Fit the height into [-1, 1].
    const points = [...segments.map((s) => s.to), ...leaves.map((l) => l.at)];
    const top = Math.max(...points.map((p) => p[ 1 ]));
    const reach = Math.max(...points.map((p) => Math.hypot(p[ 0 ], p[ 2 ])));
    // Height fits the screen; the crown may run past the sides.
    const size = (2 * SCALE) / Math.max(top, reach * 0.6);
    const fit = ([x, y, z]: Vec): Vec => [x * size, y * size - 1, z * size];

    return {
        segments: segments.map((s) => ({...s, from: fit(s.from), to: fit(s.to)})),
        leaves  : leaves.map((l) => ({...l, at: fit(l.at)})),
    };
}

const stroke = (dx: number, dy: number, aspect: number) => {
    const across = Math.abs(dx * aspect);
    const down = Math.abs(dy);
    if (down > across * 2.2) return "|";

    if (across > down * 2.2) return "_";

    return dx * dy > 0 ? "\\" : "/";
};

export function drawWood(overlay: Overlay, camera: Camera, tree: Tree) {
    const {aspect, radius, zoom} = camera.view;
    const a: Point = {x: 0, y: 0, z: 0}, b: Point = {x: 0, y: 0, z: 0};
    const girth = Math.min(Math.round(MAX_GIRTH * zoom), Math.round(radius / 3));
    for (const s of tree.segments) {
        project(camera, s.from[ 0 ], s.from[ 1 ], s.from[ 2 ], a);
        project(camera, s.to[ 0 ], s.to[ 1 ], s.to[ 2 ], b);
        const dx = b.x - a.x, dy = b.y - a.y;
        const steps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy))));
        const char = s.depth === 0 ? "#" : stroke(dx, dy, aspect);
        const color = s.depth < 3 ? BARK : TWIG_INK;
        const kind = s.depth < 3 ? CELL.wood : CELL.twig;
        const flat = Math.abs(dx * aspect) > Math.abs(dy);
        for (let i = 0; i <= steps; i++) {
            const t = i / steps;
            const x = a.x + dx * t, y = a.y + dy * t, z = a.z + (b.z - a.z) * t;
            const width = Math.max(1, Math.round(girth * TAPER ** (s.level + t / PIECES)));
            const left = -((width - 1) >> 1);
            // Offset across the stroke: sideways for upright limbs, vertically for flat ones.
            for (let w = left; w < left + width; w++) plot(overlay, flat ? x : x + w, flat ? y + w * aspect : y, z, char, color, kind);
        }
    }
}
