import {COAL} from "../theme";
import {project, type Camera, type Point} from "./camera";
import {CELL, plot, type Overlay} from "./overlay";
import {drawWood, type Segment} from "./tree";

type Vec = [x: number, y: number, z: number];

// Things around the pine, placed on the ground by angle and distance from the trunk, each turned by its own spin.
type Spot = {
    angle: number;
    reach: number;
    spin : number;
};

export type Yard = {
    snowman: Spot;
};

const SUN = (() => {
    const [x, y, z] = [-0.5, 0.8, -0.3], len = Math.hypot(x, y, z);

    return [x / len, y / len, z / len];
})();

// Snowman spheres, bottom up: centre height and radius.
const BALLS = [[-0.9, 0.11], [-0.73, 0.08], [-0.605, 0.06]] as const;

export function growYard(random: () => number): Yard {
    return {
        snowman: {angle: random() * Math.PI * 2, reach: 0.95, spin: random() * Math.PI * 2},
    };
}

// Turns a point from the thing's own frame (u across, v along, y up) into the world, then onto the screen.
function placer(camera: Camera, {angle, reach, spin}: Spot, p: Point) {
    const cx = Math.cos(angle) * reach, cz = Math.sin(angle) * reach, cos = Math.cos(spin), sin = Math.sin(spin);

    return (u: number, v: number, y: number) => project(camera, cx + u * cos - v * sin, y, cz + u * sin + v * cos, p);
}

// Small enough that neighbouring samples land in neighbouring cells, so surfaces have no holes.
const stepFor = ({view}: Camera) => (Math.min(view.aspect, 1) / Math.max(1, view.radius)) * 0.6;

const tone = (nx: number, ny: number, nz: number) => {
    const light = nx * SUN[ 0 ]! + ny * SUN[ 1 ]! + nz * SUN[ 2 ]!;

    return light > 0.45 ? 0 : light > -0.1 ? 1 : 2;
};

export function drawYard(overlay: Overlay, camera: Camera, yard: Yard) {
    const p: Point = {x: 0, y: 0, z: 0};
    drawSnowman(overlay, camera, yard.snowman, p);
}

function drawSnowman(overlay: Overlay, camera: Camera, spot: Spot, p: Point) {
    const at = placer(camera, spot, p);
    const step = stepFor(camera);
    const cos = Math.cos(spot.spin), sin = Math.sin(spot.spin);
    // Sphere normals are lit in the world, so the shading stays put while the snowman turns with the view.
    const worldNormal = (u: number, v: number, y: number): Vec => [u * cos - v * sin, y, u * sin + v * cos];
    for (const [cy, r] of BALLS) {
        const rings = Math.max(4, Math.ceil((Math.PI * r) / step));
        for (let i = 0; i <= rings; i++) {
            const theta = (i / rings) * Math.PI, ring = Math.sin(theta) * r;
            const around = Math.max(6, Math.ceil((Math.PI * 2 * ring) / step));
            for (let j = 0; j < around; j++) {
                const phi = (j / around) * Math.PI * 2;
                const nu = Math.sin(theta) * Math.cos(phi), ny = Math.cos(theta), nv = Math.sin(theta) * Math.sin(phi);
                at(nu * r, nv * r, cy + ny * r);
                plot(overlay, p.x, p.y, p.z, " ", COAL, CELL.snow3 + tone(...worldNormal(nu, nv, ny)));
            }
        }
    }

    // The face looks along -v. Coal eyes and buttons sit on the surface, the carrot sticks out of it.
    const [, [middleY, middleR], [headY, headR]] = BALLS;
    const coal = (u: number, y: number, ball: number, cy: number) => {
        const v = -Math.sqrt(Math.max(0, ball * ball - u * u - (y - cy) * (y - cy)));
        at(u, v, y);
        plot(overlay, p.x, p.y, p.z - 0.01, "•", COAL, CELL.snow3 + 1);
    };

    coal(-0.022, headY + 0.018, headR, headY);
    coal(0.022, headY + 0.018, headR, headY);
    for (const dy of [0.035, 0, -0.035]) coal(0, middleY + dy, middleR, middleY);
    for (let v = -headR; v > -headR - 0.07; v -= step) {
        at(0, v, headY - 0.005);
        plot(overlay, p.x, p.y, p.z - 0.01, " ", COAL, CELL.carrot);
    }

    // Scarf round the neck, hat on top.
    for (let a = 0; a < Math.PI * 2; a += step / headR) {
        for (const dy of [0, step]) {
            at(Math.cos(a) * headR * 0.95, Math.sin(a) * headR * 0.95, headY - headR * 0.8 + dy);
            plot(overlay, p.x, p.y, p.z - 0.005, " ", COAL, CELL.gift + 1);
        }
    }
    const crown = headY + headR * 0.85;
    for (const [r, from, to] of [[headR * 1.15, crown, crown + step], [headR * 0.7, crown, crown + 0.07]] as const) {
        for (let y = from; y <= to; y += step) {
            for (let a = 0; a < Math.PI * 2; a += step / r) {
                at(Math.cos(a) * r, Math.sin(a) * r, y);
                plot(overlay, p.x, p.y, p.z, " ", COAL, CELL.hat);
            }
        }
    }

    // Twig arms out of the middle ball.
    const arms: Segment[] = [-1, 1].map((side) => {
        const from = worldAt(spot, side * middleR * 0.9, 0, middleY + 0.01);

        return {from, to: worldAt(spot, side * (middleR + 0.12), 0, middleY + 0.07), depth: 3, level: 3};
    });

    drawWood(overlay, camera, {segments: arms, leaves: []});
}

const worldAt = ({angle, reach, spin}: Spot, u: number, v: number, y: number): Vec => {
    const cos = Math.cos(spin), sin = Math.sin(spin);

    return [Math.cos(angle) * reach + u * cos - v * sin, y, Math.sin(angle) * reach + u * sin + v * cos];
};
