// What a frame looks at: the tree's place on screen, the ground line and the moment in time.
export type View = {
    aspect : number;
    cx     : number;
    cy     : number;
    radius : number;
    time   : number;
    yaw    : number;
    horizon: number;
    zoom   : number; // cells per cell at 100% browser zoom
};

export type Point = {
    x: number;
    y: number;
    z: number;
};

export type Camera = {
    view: View;
    sinY: number;
    cosY: number;
};

const PITCH = 0.12;
const SIN_X = Math.sin(PITCH), COS_X = Math.cos(PITCH);

export const aimCamera = (view: View, yaw: number): Camera => ({view, sinY: Math.sin(yaw), cosY: Math.cos(yaw)});

// Writes into `out` because this runs for every segment and leaf of every frame.
export function project({view, sinY, cosY}: Camera, x: number, y: number, z: number, out: Point) {
    const rx = x * cosY + z * sinY;
    const rz = z * cosY - x * sinY;
    const py = y * COS_X - rz * SIN_X;
    const pz = y * SIN_X + rz * COS_X;
    const f = 3 / (3 + pz);

    out.x = view.cx + (rx * f * view.radius) / view.aspect;
    out.y = view.cy - py * f * view.radius;
    out.z = pz;
}
