import type {Buffer} from "@glyph-engine/web";
import {buffer as cells} from "@glyph-engine/web";

// What every UI drawing step needs for one frame.
export type Frame = {
    buffer: Buffer;
    cols  : number;
    rows  : number;
    mouseX: number;
    mouseY: number;
};

export function put({buffer, cols, rows}: Frame, text: string, x: number, y: number, style: object, maxX = cols) {
    const pen = {char: "", ...style}; // one per call, not per character: the engine copies it
    for (const char of text) {
        if (x >= maxX) return x;

        pen.char = char;
        cells.merge(pen, x++, y, buffer, cols, rows);
    }

    return x;
}
