import {CARVING, FILLS} from "../theme";
import type {View} from "./camera";
import {CELL, plot, type Overlay} from "./overlay";
import {mulberry32} from "./random";

// Anchored bottom-centre. "#" is solid stone, "▄" rounds a corner, other marks are carved.
const SHAPES = [
    {near: ["  ▄###▄  ", "▄#######▄", "#########", "###RIP###", "#########", "#########"], far: [" ▄#▄ ", "#####", "#ʳⁱᵖ#", "#####"]},
    {near: ["   ###   ", "   ###   ", "#########", "#########", "   ###   ", "   ###   ", "   ###   "], far: ["  #  ", "#####", "  #  ", "  #  ", "  #  "]},
    {near: ["#####", "#####", "##†##", "#####", "#####", "#####"], far: ["###", "#†#", "###", "###"]},
];

const COUNT = 11;
const SEED = 1337;
const MIN_RADIUS = 8; // below this the ground strip is too thin to read a grave
const NEAR_FROM = 0.3; // share of the ground, from the horizon down

type Mark = {
    dx   : number;
    dy   : number;
    char : string;
    color: string;
    kind : number;
};

// Expanded once, so drawing a grave walks a flat list instead of scanning strings every frame.
const toMarks = (pattern: string[]) => pattern.flatMap((line, row) => [...line].flatMap((mark, col): Mark[] => {
    if (mark === " ") return [];

    const at = {dx: col - (line.length >> 1), dy: row - pattern.length + 1};
    if (mark === "▄") return [{...at, char: mark, color: FILLS[ CELL.stone ]!, kind: CELL.stoneEdge}];

    return [{...at, char: mark === "#" ? " " : mark, color: CARVING, kind: CELL.stone}];
}));

const MARKS = SHAPES.map(({near, far}) => ({near: toMarks(near), far: toMarks(far)}));

const GRAVES = (() => {
    const random = mulberry32(SEED);

    return Array.from({length: COUNT}, (_, i) => ({
        angle: ((i + (random() - 0.5) * 0.6) / COUNT) * Math.PI * 2,
        reach: 0.55 + random() * 0.45,
        marks: MARKS[ Math.floor(random() * MARKS.length) ]!,
    }));
})();

// The ground has its own projection, so graves ride an ellipse around the trunk instead of the camera.
export function drawGraves(overlay: Overlay, view: View, yaw: number) {
    const {aspect, cx, cy, radius, horizon} = view;
    const size = Math.max(1, Math.round(view.zoom));
    if (radius < MIN_RADIUS) return;

    const {rows} = overlay;
    const ground = cy + radius;
    for (const {angle, reach, marks} of GRAVES) {
        const across = Math.cos(angle + yaw) * reach, toward = Math.sin(angle + yaw) * reach;
        const y = Math.round(ground + toward * (toward > 0 ? rows - 2 - ground : ground - horizon));
        const x = Math.round(cx + (across * radius * 1.7) / aspect);
        const near = (y - horizon) / (rows - horizon) > NEAR_FROM;
        for (const mark of near ? marks.near : marks.far) drawMark(overlay, mark, x, y, -toward, size);
    }
}

// One pattern cell as a size x size block: stone fills it, a carving sits in its middle, a rounded corner keeps its lower half.
function drawMark(overlay: Overlay, {dx, dy, char, color, kind}: Mark, x: number, y: number, z: number, size: number) {
    const left = x + dx * size - (size >> 1), top = y + (dy - 1) * size + 1;
    const edgeRow = kind === CELL.stoneEdge ? (size - 1) >> 1 : -1;
    for (let row = Math.max(0, edgeRow); row < size; row++) {
        for (let col = 0; col < size; col++) {
            if (row === edgeRow) plot(overlay, left + col, top + row, z, char, color, kind);
            else if (row === size >> 1 && col === size >> 1 && kind !== CELL.stoneEdge) plot(overlay, left + col, top + row, z, char, color, kind);
            else plot(overlay, left + col, top + row, z, " ", CARVING, CELL.stone);
        }
    }
}
