import {FIREWORKS} from "../theme";
import type {View} from "./camera";
import {emit} from "./glow";
import {CELL, plot, type Overlay} from "./overlay";

const SHELLS = 5;
const SPARKS = 28;
const RISE_MS = 900, BURST_MS = 1700;
const DEPTH = 8; // far behind the tree, so the tree hides any shell behind it

const hash = (a: number, b: number) => {
    const n = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;

    return n - Math.floor(n);
};

// Shells on staggered loops: each rises from the horizon, bursts into a ring of sparks that sag and fade, and lights the sky around it.
export function drawFireworks(overlay: Overlay, {aspect, horizon, time, radius}: View) {
    const {cols} = overlay;
    for (let s = 0; s < SHELLS; s++) {
        const period = RISE_MS + BURST_MS + 600 + s * 470;
        const local = time + s * 1311, round = Math.floor(local / period), age = local % period;
        const x = cols * (0.08 + 0.84 * hash(s, round)), top = horizon * (0.12 + 0.3 * hash(round, s));
        const color = FIREWORKS[ Math.floor(hash(s + 7, round) * FIREWORKS.length) ]!;
        if (age < RISE_MS) {
            const y = horizon - (horizon - top) * (age / RISE_MS);
            plot(overlay, x, y, DEPTH, "|", color, CELL.snow);
            plot(overlay, x, y + 1, DEPTH, "'", color, CELL.snow);
            continue;
        }

        const burst = (age - RISE_MS) / BURST_MS;
        if (burst >= 1) continue;

        const reach = radius * 0.35 * Math.sqrt(burst), sag = radius * 0.12 * burst * burst;
        for (let i = 0; i < SPARKS; i++) {
            const a = (i / SPARKS) * Math.PI * 2 + round;
            plot(overlay, x + (Math.cos(a) * reach) / aspect, top + Math.sin(a) * reach * 0.9 + sag, DEPTH, burst < 0.4 ? "*" : burst < 0.75 ? "+" : "·", color, CELL.snow);
        }
        plot(overlay, x, top + sag, DEPTH, "·", color, CELL.snow);
        emit(overlay, x, top + sag, DEPTH, color, radius * 0.45, 1.2 * (1 - burst));
    }
}
