import {run, type WebSettings} from "@glyph-engine/web";
import {langs, type Lang} from "./cv/data";
import {setLang} from "./rendering/actions";
import {bindInput} from "./rendering/input";
import {createProgram} from "./rendering/program";
import {createApp, selectTab} from "./rendering/state";
import {tabIndexFor} from "./terminal/pages";
import {c} from "./theme";

const root = document.getElementById("root")!;

const savedLang = () => {
    try {
        return localStorage.getItem("lang");
    } catch {
        return null;
    }
};

const params = new URLSearchParams(location.search);
const app = createApp({
    reduced: matchMedia("(prefers-reduced-motion: reduce)").matches,
    hover  : matchMedia("(hover: hover)").matches,
    // Each visit gets its own tree, unchanged for as long as the page stays open.
    seed   : crypto.getRandomValues(new Uint32Array(1))[ 0 ]!,
    piece  : params.get("scene"),
});

const wanted = params.get("lang") ?? savedLang();
setLang(app, langs.includes(wanted as Lang) ? (wanted as Lang) : "en");
selectTab(app, tabIndexFor(params.get("tab")));
// `?bar=0` hides the tab bar, for embeds and screenshots; number keys still switch tabs.
app.tabBar = params.get("bar") !== "0";

const fontFamily = '"0xProtoNerdFontMono", monospace';
// Fixed at load: the engine measures cells once and never re-measures.
const small = innerWidth < 768;
const fontSize = small ? "13px" : "16px";
await Promise.all([
    document.fonts.load(`${fontSize} ${fontFamily}`, "A"),
    document.fonts.load(`bold ${fontSize} ${fontFamily}`, "A"),
]);

// WebGL on a real GPU draws the grid in one call; software WebGL (SwiftShader, llvmpipe) is slower than canvas, so it counts as none.
function pickRenderer() {
    const gl = document.createElement("canvas").getContext("webgl2", {failIfMajorPerformanceCaveat: true});
    if (!gl) return "canvas";

    const info = gl.getExtension("WEBGL_debug_renderer_info");
    const gpu = info ? String(gl.getParameter(info.UNMASKED_RENDERER_WEBGL)) : "";
    gl.getExtension("WEBGL_lose_context")?.loseContext();

    return /swiftshader|llvmpipe|softpipe|software|basic render driver/i.test(gpu) ? "canvas" : "webgl";
}

const settings: WebSettings = {
    element        : root,
    cols           : 0,
    rows           : 0,
    once           : false,
    fps            : 12,
    renderer       : pickRenderer(),
    allowSelect    : false,
    restoreState   : false,
    backgroundColor: c.crust,
    fontFamily,
    fontSize,
    // Below the font content height so inline backgrounds overlap and leave no seams between rows.
    lineHeight     : small ? "15px" : "18px",
};

run(createProgram(app), settings);
bindInput(root, app);
