export const ROOMY_COLS = 84; // below this the window fills the width and touch hints replace key hints
export const COMPACT_TAB_COLS = 106; // below this tabs shrink to equal slots with short names
const WIDE_COLS = 130; // from here the window sits beside the tree
const MAX_WINDOW_WIDTH = 104;
const WINDOW_MARGIN = 3;
const HORIZON = 0.8; // share of the height above the ground

// Browser zoom below 100% packs more cells into the same screen; sizes in cells grow by this so the picture keeps its proportions.
// shortcut: reads devicePixelRatio, so on a HiDPI screen zoom only counts once it drops the ratio below 1; upgrade by remembering the ratio at load.
export const zoomOut = () => Math.max(1, 1 / (globalThis.devicePixelRatio || 1));

const groundedTree = (rows: number, width: number, cx: number, aspect: number) => {
    const horizon = Math.round(rows * HORIZON);
    const base = horizon + 2;
    const radius = Math.min((base - 2) / 2, width * aspect * 0.5);

    return {horizon, tree: {cx, cy: base - radius, radius}};
};

// Wide: window left, where the eye lands first, tree right. Otherwise: tree in a strip above a full-width window.
export function layout(cols: number, rows: number, aspect = 0.5, bare = false, maxWidth = MAX_WINDOW_WIDTH, zoom = 1) {
    if (bare) return {win: {x: 0, y: 0, w: 0, h: 0}, ...groundedTree(rows, cols, cols / 2, aspect)};

    if (cols >= WIDE_COLS * zoom) {
        const w = Math.round(Math.min(maxWidth * zoom, cols - 44 * zoom));
        const side = cols - w - WINDOW_MARGIN;

        return {win: {x: WINDOW_MARGIN, y: 2, w, h: rows - 3}, ...groundedTree(rows, side, cols - side / 2, aspect)};
    }

    const strip = rows >= 26 ? Math.max(5, Math.min(12, Math.round(rows * 0.25))) : 0;
    const roomy = cols >= ROOMY_COLS;
    const w = roomy ? Math.min(Math.round(maxWidth * zoom), cols - 4) : cols;
    const y = 1 + strip;

    return {
        win    : {x: Math.floor((cols - w) / 2), y, w, h: rows - y - (roomy ? 1 : 0)},
        horizon: strip ? y - Math.max(1, Math.round(strip * 0.2)) : rows - 2,
        tree   : {cx: cols / 2, cy: y - 0.5 - (strip - 0.5) / 2, radius: (strip - 0.5) / 2},
    };
}
