import type {Overlay} from "./overlay";

// Colour per css string, parsed once: "rgb(r,g,b)" from the gradients and shading, "#rrggbb" from the theme.
const parsed = new Map<string, number[]>();
function channels(css: string) {
    let rgb = parsed.get(css);
    if (!rgb) {
        rgb = css.startsWith("#") ? [1, 3, 5].map((at) => parseInt(css.slice(at, at + 2), 16)) : css.slice(4, -1).split(",").map(Number);
        parsed.set(css, rgb);
    }

    return rgb;
}

// A light at a cell, spreading `hex` over `reach` rows (wider across, by the cell aspect) with a soft falloff.
export function emit(overlay: Overlay, x: number, y: number, z: number, hex: string, reach: number, strength: number) {
    overlay.emitters.push({x: Math.round(x), y: Math.round(y), z: Math.fround(z), rgb: channels(hex), reach, strength});
}

// Adds every visible light into the glow buffer; a light hidden behind something nearer stays dark.
export function glowPass(overlay: Overlay, aspect: number) {
    const {cols, rows, depth, glow, emitters} = overlay;
    for (const {x, y, z, rgb, reach, strength} of emitters) {
        if (x < 0 || x >= cols || y < 0 || y >= rows || depth[ x + y * cols ] !== z) continue;

        const across = Math.ceil(reach / aspect), up = Math.ceil(reach);
        for (let dy = -up; dy <= up; dy++) {
            const row = y + dy;
            if (row < 0 || row >= rows) continue;

            for (let dx = -across; dx <= across; dx++) {
                const col = x + dx;
                const d = Math.hypot(dx * aspect, dy) / reach;
                if (col < 0 || col >= cols || d >= 1) continue;

                const f = (1 - d) * (1 - d) * strength, at = (col + row * cols) * 3;
                glow[ at ]! += rgb[ 0 ]! * f;
                glow[ at + 1 ]! += rgb[ 1 ]! * f;
                glow[ at + 2 ]! += rgb[ 2 ]! * f;
            }
        }
    }
    emitters.length = 0;
}

const add = (css: string, glow: Float32Array, at: number, k: number) => {
    const [r, g, b] = channels(css) as [number, number, number];

    return `rgb(${Math.min(255, r + glow[ at ]! * k) | 0},${Math.min(255, g + glow[ at + 1 ]! * k) | 0},${Math.min(255, b + glow[ at + 2 ]! * k) | 0})`;
};

// Light falls on the glyph more than on the cell behind it, so lit needles and snow stand out.
type Lit = {
    color          : string;
    backgroundColor: string;
};

export function lit<Cell extends Lit>(cell: Cell, glow: Float32Array, index: number) {
    const at = index * 3;
    if (glow[ at ]! + glow[ at + 1 ]! + glow[ at + 2 ]! < 6) return cell;

    cell.color = add(cell.color, glow, at, 0.9);
    cell.backgroundColor = add(cell.backgroundColor, glow, at, 0.45);

    return cell;
}
