import {FILLS} from "../theme";

// Screen-sized buffers the tree, graves and snow draw into, nearest cell winning.
export type Overlay = {
    cols    : number;
    rows    : number;
    depth   : Float32Array;
    chars   : string[];
    colors  : string[];
    kinds   : Uint8Array;
    light   : Float32Array;
    glow    : Float32Array; // rgb light added per cell, 3 floats each
    emitters: {
        x       : number;
        y       : number;
        z       : number;
        rgb     : number[];
        reach   : number;
        strength: number;
    }[];
};

export const CELL = {wood: 0, leaf: 1, autumnLeaf: 2, twig: 3, goldLeaf: 4, snow: 5, stone: 6, stoneEdge: 7, gift: 8, ribbon: 20, snow3: 22, carrot: 25, hat: 26, star: 27} as const; // gift + 3 * wrap + face, ribbon + colour, snow3 + tone, star + facet

export const createOverlay = (cols: number, rows: number): Overlay => {
    const cells = cols * rows;

    return {cols, rows, depth: new Float32Array(cells), chars: new Array(cells), colors: new Array(cells), kinds: new Uint8Array(cells), light: new Float32Array(cells), glow: new Float32Array(cells * 3), emitters: []};
};

export function plot({cols, rows, depth, chars, colors, kinds}: Overlay, x: number, y: number, z: number, char: string, color: string, kind: number) {
    const col = Math.round(x);
    const row = Math.round(y);
    if (col < 0 || col >= cols || row < 0 || row >= rows) return;

    const index = col + row * cols;
    if (z >= depth[ index ]!) return;

    depth[ index ] = z;
    chars[ index ] = char;
    colors[ index ] = color;
    kinds[ index ] = kind;
}

const isLeaf = (kind: number) => kind !== CELL.wood && kind !== CELL.twig;

// Wood and stone are opaque. Leaves fill only when surrounded, so the crown edge stays airy.
// Twigs show the sky, except inside foliage, where the sky would punch holes in the canopy.
export function fillAt({cols, depth, kinds}: Overlay, index: number) {
    const kind = kinds[ index ]!;
    if (kind === CELL.wood || kind === CELL.stone || kind >= CELL.gift) return FILLS[ kind ];

    let around = 0, leaves = 0, firstLeaf = 0;
    for (let n = 0; n < 4; n++) {
        const i = n === 0 ? index - 1 : n === 1 ? index + 1 : n === 2 ? index - cols : index + cols;
        if (!(depth[ i ]! < Infinity)) continue;

        around++;
        if (!isLeaf(kinds[ i ]!)) continue;

        if (leaves++ === 0) firstLeaf = kinds[ i ]!;
    }
    if (kind !== CELL.twig) return around >= 3 ? FILLS[ kind ] : undefined;

    return leaves >= 2 ? FILLS[ firstLeaf ] : undefined;
}
