import {drawbox} from "@glyph-engine/web";
import {langs} from "../cv/data";
import type {Hole} from "../scene/background";
import type {Tab} from "../terminal/pages";
import {c} from "../theme";
import {put, type Frame} from "./frame";
import type {App} from "./state";

const LANG_WIDTH = 4;

export function drawWindow(frame: Frame, app: App, win: Hole, tab: Tab) {
    const {buffer, cols, rows, mouseX, mouseY} = frame;
    drawbox.drawBox("", {
        x              : win.x, y              : win.y, width          : win.w, height         : win.h, borderStyle    : "round", shadowStyle    : "none",
        paddingX       : 0, paddingY       : 0, color          : c.accent, backgroundColor: c.base, fontWeight     : "normal",
    }, buffer, cols, rows);

    let langX = win.x + win.w - 2 - langs.length * LANG_WIDTH;
    put(frame, ` nicolas@medis: ${tab.dir} `, win.x + 2, win.y, {color: c.text, fontWeight: "bold"}, langX);
    for (const lang of langs) {
        const active = lang === app.lang;
        const hover = app.hover && mouseY === win.y && mouseX >= langX && mouseX < langX + LANG_WIDTH;
        put(frame, ` ${lang} `, langX, win.y, {
            color          : active ? c.crust : hover ? c.accent : c.sub,
            backgroundColor: active ? c.accent : c.base,
            fontWeight     : active ? "bold" : "normal",
        });
        app.hits.push({x0: langX, x1: langX + LANG_WIDTH, y: win.y, action: {kind: "lang", lang}});
        langX += LANG_WIDTH;
    }
}
