import type {Lang} from "../cv/data";
import type {Line} from "../terminal/lines";
import {tabs, tabSlug} from "../terminal/pages";
import {c} from "../theme";
import {createRoot, expandHome, lookup, plainLine, resolvePath, type DirNode, type FsNode} from "./filesystem";
import {clearScreen, closeShell, type Shell} from "./shell";

export type Env = {
    width: number;
    lang : Lang;
};

type Command = (args: string[], shell: Shell, env: Env) => Line[];

const say = (...lines: string[]) => lines.map(plainLine);
const BUILT_AT = "Nov  1 12:00";

const words = (args: string[]) => args.filter((a) => !a.startsWith("-"));
const has = (args: string[], flag: string) => args.some((a) => a.startsWith("-") && !a.startsWith("--") && a.includes(flag));

const denied = (name: string, message: (target: string) => string): Command => (args) => {
    const targets = words(args);

    return say(...(targets.length ? targets.map(message) : [`${name}: missing file operand`]));
};

const denyEdit = (name: string) => denied(name, (target) => `${name}: ${target}: Permission denied`);

const visibleNames = (entries: Record<string, FsNode>, all: boolean) => Object.keys(entries).filter((name) => all || !name.startsWith(".")).sort();
const nameSpan = (name: string, node: FsNode) => ({text: name, color: node.kind === "dir" ? c.blue : c.text, bold: node.kind === "dir"});

function longRow(name: string, node: FsNode): Line {
    const mode = node.locked ? "d---------" : node.kind === "dir" ? "dr-xr-xr-x" : "-r--r--r--";

    return [{text: `${mode} 1 root root 4096 ${BUILT_AT} `, color: c.dim}, nameSpan(name, node)];
}

// Fills rows up to the width instead of real columns, which is enough for these short listings.
function gridRows(names: string[], dir: DirNode, width: number) {
    if (!names.length) return [];

    const rows: Line[] = [[]];
    let used = 0;
    for (const name of names) {
        if (used + name.length + 2 > width && used) {
            rows.push([]);
            used = 0;
        }

        rows.at(-1)!.push(nameSpan(name, dir.entries[ name ]!), {text: "  ", color: c.text});
        used += name.length + 2;
    }

    return rows;
}

const ls: Command = (args, shell, {width}) => {
    const targets = words(args);

    return (targets.length ? targets : ["."]).flatMap((target) => {
        const node = lookup(shell.root, resolvePath(shell.cwd, target));
        if (!node) return say(`ls: cannot access '${target}': No such file or directory`);

        if (node.locked) return say(`ls: cannot open directory '${target}': Permission denied`);

        if (node.kind === "file") return has(args, "l") ? [longRow(target, node)] : say(target);

        const names = visibleNames(node.entries, has(args, "a"));

        return has(args, "l") ? names.map((name) => longRow(name, node.entries[ name ]!)) : gridRows(names, node, width);
    });
};

const cd: Command = (args, shell) => {
    const target = words(args)[ 0 ] ?? "~";
    const path = resolvePath(shell.cwd, target);
    const node = lookup(shell.root, path);
    if (!node) return say(`cd: no such file or directory: ${target}`);

    if (node.kind !== "dir") return say(`cd: not a directory: ${target}`);

    if (node.locked) return say(`cd: permission denied: ${target}`);

    shell.cwd = path;

    return [];
};

const reader = (name: string): Command => (args, shell, {width, lang}) => {
    const targets = words(args);
    if (!targets.length) return say(`${name}: missing file operand`);

    return targets.flatMap((target) => {
        const node = lookup(shell.root, resolvePath(shell.cwd, target));
        if (!node) return say(`${name}: ${target}: No such file or directory`);

        if (node.locked) return say(`${name}: ${target}: Permission denied`);

        if (node.kind === "dir") return say(`${name}: ${target}: Is a directory`);

        return node.read(width, lang);
    });
};

function treeRows(dir: DirNode, prefix: string): Line[] {
    const names = visibleNames(dir.entries, false);

    return names.flatMap((name, i) => {
        const node = dir.entries[ name ]!;
        const last = i === names.length - 1;
        const row: Line = [{text: `${prefix}${last ? "└── " : "├── "}`, color: c.dim}, nameSpan(name, node)];
        if (node.kind !== "dir" || node.locked) return [row];

        return [row, ...treeRows(node, `${prefix}${last ? "    " : "│   "}`)];
    });
}

const tree: Command = (args, shell) => {
    const target = words(args)[ 0 ] ?? ".";
    const node = lookup(shell.root, resolvePath(shell.cwd, target));
    if (!node || node.kind !== "dir" || node.locked) return say(`${target} [error opening dir]`);

    return [[{text: target, color: c.blue, bold: true}], ...treeRows(node, "")];
};

const askPassword = (prompt: string, tries: number, failure: string): Command => (args, shell) => {
    shell.password = {prompt, tries, failure};

    return [];
};

const fastfetch: Command = (_args, _shell, {width, lang}) => tabs[ 0 ]!.body(width, lang);

const commands: Record<string, Command> = {
    bat  : reader("bat"),
    cat  : reader("cat"),
    cd,
    chmod: denyEdit("chmod"),
    chown: denyEdit("chown"),
    clear: (_args, shell) => {
        clearScreen(shell);

        return [];
    },
    cp  : denyEdit("cp"),
    date: () => say(new Date().toString()),
    echo: (args) => say(args.join(" ")),
    exit: (_args, shell) => {
        closeShell(shell);

        return [];
    },
    fastfetch,
    head    : reader("head"),
    help    : () => say(`Commands: ${Object.keys(commands).sort().join(" ")}`),
    history : (_args, shell) => say(...shell.commandHistory.map((line, i) => `${String(i + 1).padStart(4)}  ${line}`)),
    hostname: () => say("medis"),
    id      : () => say("uid=1000(nicolas) gid=1000(nicolas) groups=1000(nicolas)"),
    ln      : denyEdit("ln"),
    ls,
    man     : (args) => say(`No manual entry for ${args[ 0 ] ?? ""}`.trim()),
    medis   : (_args, shell) => {
        shell.openTab = tabs.findIndex((tab) => tabSlug(tab) === "medis");

        return [];
    },
    mkdir   : denied("mkdir", (target) => `mkdir: cannot create directory '${target}': Permission denied`),
    mv      : denyEdit("mv"),
    nano    : denyEdit("nano"),
    neofetch: fastfetch,
    nvim    : denyEdit("nvim"),
    pwd     : (_args, shell) => say(shell.cwd),
    rm      : denied("rm", (target) => `rm: cannot remove '${target}': Permission denied`),
    rmdir   : denied("rmdir", (target) => `rmdir: failed to remove '${target}': Permission denied`),
    su      : askPassword("Password: ", 1, "su: Authentication failure"),
    sudo    : askPassword("[sudo] password for nicolas: ", 3, "sudo: 3 incorrect password attempts"),
    touch   : denied("touch", (target) => `touch: cannot touch '${target}': Permission denied`),
    tree,
    uname   : (args) => say(has(args, "a") ? "Linux medis 7.2.0-medis #1 SMP x86_64 GNU/Linux" : "Linux"),
    vi      : denyEdit("vi"),
    vim     : denyEdit("vim"),
    which   : (args) => say(...args.map((name) => (commands[ name ] ? `/usr/bin/${name}` : `${name} not found`))),
    whoami  : () => say("nicolas"),
};

export const commandNames = Object.keys(commands);
export const createFilesystem = () => createRoot(commandNames);

const TOKEN = /"([^"]*)"|'([^']*)'|(\S+)/g;
const tokenize = (line: string) => Array.from(line.matchAll(TOKEN), (m) => m[ 1 ] ?? m[ 2 ] ?? m[ 3 ]!);

// shortcut: only expands * in the current directory, enough for the "bat *.md" the tabs show.
function expandGlob(word: string, shell: Shell) {
    if (!word.includes("*") || word.includes("/")) return [word];

    const cwd = lookup(shell.root, shell.cwd) as DirNode;
    const pattern = new RegExp(`^${word.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*")}$`);

    return Object.keys(cwd.entries).filter((name) => !name.startsWith(".") && pattern.test(name)).sort();
}

export function execute(line: string, shell: Shell, env: Env): Line[] {
    const tokens = tokenize(line);
    const redirect = tokens.findIndex((t) => t === ">" || t === ">>");
    if (redirect >= 0) return say(`zsh: permission denied: ${tokens[ redirect + 1 ] ?? ""}`.trim());

    // shortcut: no pipes or chaining, an easter egg does not need a real parser; add one if it ever grows.
    if (tokens.some((t) => t === "|" || t === "&&" || t === ";")) return say("zsh: pipes and chaining are not installed on MedisOS");

    const [name, ...rest] = tokens;
    if (!name) return [];

    const command = commands[ name ];
    if (!command) return say(`zsh: command not found: ${name}`);

    const args: string[] = [];
    for (const word of rest) {
        const matches = expandGlob(word, shell);
        if (!matches.length) return say(`zsh: no matches found: ${word}`);

        args.push(...matches);
    }

    return command(args.map(expandHome), shell, env);
}
