import type {Lang} from "../cv/data";

// Interface text. The fastfetch rows are a hand-picked digest of master*.md; update them together.
// First professional role, from the CV. Anniversaries pass on their own at each page load.
const CAREER_START = Date.UTC(2018, 7, 1);
export const careerYears = (now = Date.now()) => new Date(now - CAREER_START).getUTCFullYear() - 1970;
// Lithuanian plural: 10, 20 and 11-19 take the genitive.
export const metai = (n: number) => (n % 10 === 0 || (n % 100 > 10 && n % 100 < 20) ? "metų" : "metai");

