import type {Block, Link} from "../cv/parse";
import {c} from "../theme";

export type Span = {
    text : string;
    color: string;
    bold?: boolean;
    url? : string;
};

export type Line = Span[];

// Greedy word wrap returning [start, end) ranges, so link offsets survive wrapping.
export function wrapRanges(text: string, width: number): [number, number][] {
    const ranges: [number, number][] = [];
    let start = 0;
    while (start < text.length) {
        let end = start + width;
        if (end >= text.length) end = text.length;
        else {
            const space = text.lastIndexOf(" ", end);
            if (space > start) end = space;
        }

        ranges.push([start, end]);
        start = end;
        while (text[ start ] === " ") start++;
    }

    return ranges;
}

function cut(text: string, [from, to]: [number, number], links: Link[], color: string, bold: boolean, keyEnd: number): Line {
    const edges = new Set([from, to]);
    for (const n of [keyEnd, ...links.flatMap((l) => [l.start, l.end])]) if (n > from && n < to) edges.add(n);
    const points = [...edges].sort((a, b) => a - b);

    return points.slice(0, -1).map((start, i) => {
        const link = links.find((l) => start >= l.start && start < l.end);
        const isKey = start < keyEnd;

        return {
            text : text.slice(start, points[ i + 1 ]),
            color: link ? c.link : isKey ? c.mauve : color,
            bold : bold || isKey,
            url  : link?.url,
        };
    });
}

export function blockLines(block: Block, width: number): Line[] {
    const {text, links, kind} = block;
    const indent = kind === "item" ? 2 : 0;
    const color = kind === "role" ? c.yellow : kind === "meta" ? c.dim : c.text;
    const keyEnd = kind === "kv" ? text.indexOf(":") + 1 : 0;

    return wrapRanges(text, width - indent).map((range, i) => {
        const line = cut(text, range, links, color, kind === "role", keyEnd);
        if (indent) line.unshift({text: i === 0 ? "\uf444 " : "  ", color: c.teal});

        return line;
    });
}
