import {langs} from "../cv/data";
import {tabs} from "../terminal/pages";
import {clearScreen, closeShell, complete, erase, interrupt, stepHistory, submit, typeText} from "../shell/shell";
import {openShell, runHit, setLang, showTab} from "./actions";
import {hitAtPixel, scrollBy, type App} from "./state";

const TAP_SLOP_PX = 10;
const WHEEL_ROWS = 3;
const SWIPE_PX = 70;

// Not "click": rows redraw every frame, and browsers drop a click whose pressed element was replaced.
// Capture keeps the release on root for the same reason. It is still a user gesture for popup blockers.
function bindPointer(root: HTMLElement, app: App) {
    let press = {x: 0, y: 0};
    root.addEventListener("pointerdown", (e) => {
        root.setPointerCapture(e.pointerId);
        press = {x: e.clientX, y: e.clientY};
    });
    root.addEventListener("pointerup", (e) => {
        const still = Math.hypot(e.clientX - press.x, e.clientY - press.y) < TAP_SLOP_PX;
        const hit = hitAtPixel(app, e.clientX, e.clientY);
        if (e.button === 0 && still && hit) runHit(app, hit.action);
    });
}

function bindWheel(root: HTMLElement, app: App) {
    root.addEventListener("wheel", (e) => {
        e.preventDefault();
        scrollBy(app, Math.sign(e.deltaY) * WHEEL_ROWS);
    }, {passive: false});
}

function submitLine(app: App) {
    const {shell} = app;
    submit(shell, {width: app.pageWidth, lang: app.lang});
    if (shell.openTab !== null) {
        showTab(app, shell.openTab);
        shell.openTab = null;
    }
}

// Returns whether the key was the shell's, so browser shortcuts like copy keep working.
function shellKey(app: App, e: KeyboardEvent) {
    const {shell} = app;
    if (e.ctrlKey && e.key === "c") interrupt(shell);
    else if (e.ctrlKey && e.key === "l") clearScreen(shell);
    else if (e.ctrlKey || e.metaKey) return false;
    else if (e.key === "Escape") closeShell(shell);
    else if (e.key === "Enter") submitLine(app);
    else if (e.key === "Backspace") erase(shell);
    else if (e.key === "Tab") complete(shell);
    else if (e.key === "ArrowUp") stepHistory(shell, -1);
    else if (e.key === "ArrowDown") stepHistory(shell, 1);
    else if ([...e.key].length === 1) typeText(shell, e.key);
    else return false;

    app.scroll = Infinity;

    return true;
}

function bindKeys(app: App) {
    window.addEventListener("keydown", (e) => {
        if (app.shell.active) {
            if (shellKey(app, e)) e.preventDefault();

            return;
        }

        if (e.ctrlKey || e.metaKey || e.altKey) return;

        if (e.key === "Enter") {
            openShell(app);
            e.preventDefault();

            return;
        }

        const page = app.viewRows - 2;
        const actions: Record<string, () => void> = {
            j         : () => scrollBy(app, 1), ArrowDown : () => scrollBy(app, 1),
            k         : () => scrollBy(app, -1), ArrowUp   : () => scrollBy(app, -1),
            h         : () => showTab(app, app.tab - 1), ArrowLeft : () => showTab(app, app.tab - 1),
            l         : () => showTab(app, app.tab + 1), ArrowRight: () => showTab(app, app.tab + 1),
            PageDown  : () => scrollBy(app, page), " "       : () => scrollBy(app, page), PageUp    : () => scrollBy(app, -page),
            g         : () => scrollBy(app, -Infinity), Home      : () => scrollBy(app, -Infinity),
            G         : () => scrollBy(app, Infinity), End       : () => scrollBy(app, Infinity),
            L         : () => setLang(app, langs[ (langs.indexOf(app.lang) + 1) % langs.length ]!),
        };

        const number = Number(e.key);
        if (number >= 1 && number <= tabs.length) showTab(app, number - 1);
        else if (actions[ e.key ]) actions[ e.key ]!();
        else return;

        e.preventDefault();
    });
}

// Drag scrolls, a mostly horizontal swipe switches tab.
function bindTouch(root: HTMLElement, app: App) {
    let touch = {x: 0, y: 0, lastY: 0};
    root.addEventListener("touchstart", (e) => {
        const t = e.touches[ 0 ]!;
        touch = {x: t.clientX, y: t.clientY, lastY: t.clientY};
    }, {passive: true});
    root.addEventListener("touchmove", (e) => {
        const y = e.touches[ 0 ]!.clientY;
        const rows = Math.trunc((touch.lastY - y) / app.lineHeight);
        if (rows) {
            scrollBy(app, rows);
            touch.lastY = y;
        }
    }, {passive: true});
    // Capture and stop: the engine's own touchend handler reads e.touches[0], which is empty here, and throws.
    root.addEventListener("touchend", (e) => {
        e.stopImmediatePropagation();
        const t = e.changedTouches[ 0 ]!;
        const dx = t.clientX - touch.x;
        if (Math.abs(dx) > SWIPE_PX && Math.abs(dx) > 2 * Math.abs(t.clientY - touch.y)) {
            showTab(app, app.tab - Math.sign(dx));
        }
    }, {capture: true});
}

export function bindInput(root: HTMLElement, app: App) {
    bindPointer(root, app);
    bindWheel(root, app);
    bindKeys(app);
    bindTouch(root, app);
}
