import type {Context, Coord} from "@glyph-engine/web";
import {num} from "@glyph-engine/web";
import {lit} from "./glow";
import {fillAt, type Overlay} from "./overlay";
import {shadeColor} from "./lighting";
import {DRY_FAR, DRY_NEAR, FAR_RANGE, GRASS_INK, GROUND_FAR, GROUND_NEAR, NEAR_RANGE, SHADOW, SKY_DAY, SKY_DUSK, SKY_NIGHT, SNOW_FAR, SNOW_NEAR, STRAW, WHITE, AURORA, type Rgb} from "../theme";

const density = " .:-=+*#%@";
const GRASS = ".,'\"";
const PLANTS = ["\u{f0e66}", "\u{f09f1}", "\u{f024a}"];
const FIELD_OF_VIEW = 2.4;

export type Hole = {
    x: number;
    y: number;
    w: number;
    h: number;
}; // covered by the window, not shaded

export type Scene = {
    hole   : Hole;
    time   : number;
    horizon: number;
    yaw    : number;
    cx     : number;
    base   : number;
    shadow : number;
    brown  : number;
    snow   : number;
    aurora : boolean; // northern lights across the upper sky
    clouds : number; // share of the season's usual cloud cover
};

const mix = (a: Rgb, b: Rgb, t: number): Rgb => [0, 1, 2].map((i) => a[ i ]! + (b[ i ]! - a[ i ]!) * t) as Rgb;
const css = ([r, g, b]: Rgb) => `rgb(${r | 0},${g | 0},${b | 0})`;

// Global memo of a pure function, owned here: one colour per row, so the gradients are built once
// per season step instead of per cell.
let bandsKey = -1;
let sky: string[] = [];
let clouds: string[][] = [];
let stars: string[][] = [];
let auroraFill: string[][][] = [];
let auroraInk: string[][][] = [];
let ground: string[] = [];
let grass: string[] = [];
let shaded: string[][] = [];
let rangeFill: string[] = [];
let rangeEdge: string[] = [];
const CAP = css(WHITE);
const SEASON_STEPS = 12;
const step = (n: number) => Math.round(n * SEASON_STEPS);
const bandsFor = (rows: number, horizon: number, scene: Scene) => (rows * 4096 + horizon) * (SEASON_STEPS + 1) ** 2 + step(scene.brown) * (SEASON_STEPS + 1) + step(scene.snow);
function buildBands(rows: number, horizon: number, scene: Scene) {
    bandsKey = bandsFor(rows, horizon, scene);
    const brown = step(scene.brown) / SEASON_STEPS, snow = step(scene.snow) / SEASON_STEPS;
    const far = mix(mix(GROUND_FAR, DRY_FAR, brown), SNOW_FAR, snow);
    const near = mix(mix(GROUND_NEAR, DRY_NEAR, brown), SNOW_NEAR, snow);
    const ink = mix(mix(GRASS_INK, STRAW, brown), WHITE, snow);
    const ranges = [mix(FAR_RANGE, WHITE, snow * 0.35), mix(NEAR_RANGE, WHITE, snow * 0.25)];
    rangeFill = ranges.map(css);
    rangeEdge = ranges.map((rgb) => css(mix(rgb, WHITE, 0.3)));
    const [top, middle, low] = SKY_DAY.map((day, i) => mix(mix(day, SKY_DUSK[ i ]!, brown), SKY_NIGHT[ i ]!, snow)) as [Rgb, Rgb, Rgb];
    const skyRgb = Array.from({length: rows}, (_, row) => {
        const t = Math.min(1, row / Math.max(1, horizon));

        return t < 0.6 ? mix(top, middle, t / 0.6) : mix(middle, low, (t - 0.6) / 0.4);
    });

    sky = skyRgb.map(css);
    clouds = skyRgb.map((rgb) => [0.1, 0.2, 0.3, 0.4].map((t) => css(mix(rgb, WHITE, t))));
    // Faint by day, bright on autumn and winter nights.
    const night = Math.max(snow, brown * 0.6);
    stars = skyRgb.map((rgb) => [0.25 + 0.6 * night, 0.1 + 0.3 * night].map((t) => css(mix(rgb, WHITE, t))));
    // Per row, per hue (green, violet), per brightness step.
    auroraFill = skyRgb.map((rgb) => AURORA.map((hue) => Array.from({length: AURORA_STEPS}, (_, i) => css(mix(rgb, hue, (i / AURORA_STEPS) * 0.45)))));
    auroraInk = skyRgb.map((rgb) => AURORA.map((hue) => Array.from({length: AURORA_STEPS}, (_, i) => css(mix(rgb, hue, 0.35 + (i / AURORA_STEPS) * 0.6)))));
    const groundRgb = Array.from({length: rows}, (_, row) => mix(far, near, Math.max(0, row - horizon) / Math.max(1, rows - horizon)));
    ground = groundRgb.map(css);
    grass = groundRgb.map((rgb) => css(mix(rgb, ink, 0.4)));
    shaded = groundRgb.map((rgb) => [0.2, 0.4, 0.6].map((t) => css(mix(rgb, SHADOW, t))));
}

// Heights in 0..1 around the full circle, so the ranges wrap as the view turns. Layer 0 is far, 1 near.
export function ridge(angle: number, layer: 0 | 1) {
    const height = layer === 0
        ? 0.55 + 0.25 * Math.sin(3 * angle + 1) + 0.15 * Math.sin(7 * angle + 2.3) + 0.05 * Math.sin(19 * angle + 0.7)
        : 0.3 + 0.18 * Math.sin(5 * angle + 4) + 0.1 * Math.sin(11 * angle + 1) + 0.04 * Math.sin(23 * angle);

    return Math.max(0, Math.min(1, height));
}

// One object reused for every cell; main() copies it into the engine's out slot.
const cell = {char: " ", color: "", backgroundColor: "", fontWeight: "normal"};
const paint = (char: string, color: string, backgroundColor: string, fontWeight = "normal") => {
    cell.char = char;
    cell.color = color;
    cell.backgroundColor = backgroundColor;
    cell.fontWeight = fontWeight;

    return cell;
};

function mountain(x: number, y: number, cols: number, scene: Scene) {
    const tall = Math.max(2, scene.horizon * 0.22);
    for (const layer of [1, 0] as const) {
        const angle = (x / cols) * FIELD_OF_VIEW - scene.yaw * (layer ? 1.6 : 1);
        const height = ridge(angle, layer);
        const top = Math.round(scene.horizon - height * tall * (layer ? 0.7 : 1));
        if (y < top) continue;

        const fill = rangeFill[ layer ]!;
        if (y > top) return paint(" ", fill, fill);

        const columnAngle = FIELD_OF_VIEW / cols;
        const slope = ridge(angle + columnAngle, layer) - ridge(angle - columnAngle, layer);

        return paint(slope > 0.015 ? "/" : slope < -0.015 ? "\\" : "^", layer === 0 && height > 0.78 ? CAP : rangeEdge[ layer ]!, fill);
    }

    return null;
}

// Marks are fixed to the world and orbit the tree with the view.
function field(x: number, y: number, aspect: number, scene: Scene) {
    const reach = y - scene.horizon + 1;
    const across = ((x - scene.cx) * aspect * 12) / reach;
    const along = 6 / reach - 1;
    const sin = Math.sin(scene.yaw), cos = Math.cos(scene.yaw);
    const u = Math.floor((across * cos - along * sin) * 6);
    const v = Math.floor((along * cos + across * sin) * 6);
    const hash = num.fract(Math.sin(u * 127.1 + v * 311.7) * 43758.5453);
    // Soft blob under the crown, so the tree sits on the ground instead of floating over it.
    const dx = (x - scene.cx) * aspect / (scene.shadow * 1.1 || 1);
    const dy = (y - scene.base) / (scene.shadow * 0.22 + 0.5);
    const dark = 1 - dx * dx - dy * dy;
    // Snow catches the light: a few crystals flash on and off.
    if (scene.snow > 0.6 && hash > 0.992 && Math.sin(scene.time * 0.004 + hash * 5000) > 0.8) return paint("+", CAP, ground[ y ]!);

    const char = hash > 0.97 && scene.brown < 0.5 && !scene.snow ? PLANTS[ Math.floor(hash * 411) % PLANTS.length ]! : hash > 0.8 ? GRASS[ Math.floor(hash * 41) % GRASS.length ]! : " ";

    return paint(char, grass[ y ]!, dark > 0 && scene.shadow > 0 ? shaded[ y ]![ Math.floor(dark * 3) ]! : ground[ y ]!);
}

const hash = (u: number, v: number) => num.fract(Math.sin(u * 127.1 + v * 311.7) * 43758.5453);
const smooth = (t: number) => t * t * (3 - 2 * t);
function noise(x: number, y: number) {
    const u = Math.floor(x), v = Math.floor(y), fx = smooth(x - u), fy = smooth(y - v);
    const top = hash(u, v) + (hash(u + 1, v) - hash(u, v)) * fx;
    const bottom = hash(u, v + 1) + (hash(u + 1, v + 1) - hash(u, v + 1)) * fx;

    return top + (bottom - top) * fy;
}

// Star trails: the sky turns about a pole above the screen, a turn every STAR_TURN ms, each star dragging a fading tail.
const STAR_TURN = 80000;
const TRAIL = [0, 0.012, 0.024, 0.036];
// Faint to bright: "*", then Nerd Font fa-star, md-star and oct-star.
const STAR_GLYPHS = ["*", "\u{f005}", "\u{f04ce}", "\u{f41e}"];
const TWINKLE = 0.003; // radians per ms, so a star dims and brightens every couple of seconds
const turn = {time: NaN, cos: [0], sin: [0]};
// Clouds drift with the wind, gather through autumn, cover the winter sky and burn off in spring.
const WIND = 0.0004;
const cloudCover = (scene: Scene) => Math.max(scene.snow * 0.75, scene.brown * 0.6) * scene.clouds;

// Each star pulses on its own phase; at the bottom of the pulse it dims to a plain "*".
function twinkle(h: number, time: number, y: number, back: string) {
    const pulse = Math.sin(time * TWINKLE + num.fract(h * 9973) * Math.PI * 2);
    if (pulse < -0.6) return paint("*", stars[ y ]![ 1 ]!, back);

    return paint(STAR_GLYPHS[ Math.floor((h - 0.99) * 400) ]!, stars[ y ]![ 0 ]!, back);
}

// Curtains hanging from a wavy lower edge: bright at the hem, fading upward, combed into vertical rays.
// Returns 0..1 and sets `auroraHue` to 0 (green, low) or 1 (violet, high).
const AURORA_STEPS = 7;
let auroraHue = 0;
function auroraAt(x: number, y: number, aspect: number, unit: number, horizon: number, time: number) {
    const ax = (x * aspect) / unit;
    const wave = Math.sin(ax * 0.12 + time * 0.00025) + 0.6 * Math.sin(ax * 0.31 - time * 0.0004 + 1.3);
    const above = (horizon * (0.3 + 0.07 * wave) - y) / (horizon * 0.16);
    if (above < -0.4 || above > 2.5) return 0;

    auroraHue = above > 0.9 ? 1 : 0;
    const band = above < 0 ? Math.exp(-above * above * 12) : Math.exp(-above * 1.3);
    const rays = 0.8 + 0.2 * Math.sin(ax * 2.7 + Math.sin(ax * 0.5 + time * 0.0006) * 3);

    return band * rays * (0.6 + 0.4 * Math.sin(time * 0.0007 + ax * 0.15));
}

// Now and then a meteor streaks across the upper sky, a bright head with a fading tail.
const METEOR_EVERY = 14000, METEOR_MS = 900;
function meteorAt(x: number, y: number, aspect: number, cols: number, horizon: number, time: number) {
    const age = time % METEOR_EVERY;
    if (age >= METEOR_MS) return -1;

    const n = Math.floor(time / METEOR_EVERY);
    const dir = hash(n, 3) > 0.5 ? 1 : -1;
    const run = cols * aspect * 0.35, progress = age / METEOR_MS;
    const headX = (cols * (0.15 + hash(n, 1) * 0.7)) * aspect + dir * run * (progress - 0.5);
    const headY = horizon * (0.1 + hash(n, 2) * 0.3) + run * 0.35 * progress;
    const len = Math.hypot(1, 0.35), ux = (dir * 1) / len, uy = 0.35 / len;
    const px = (x + 0.5) * aspect - headX, py = y + 0.5 - headY;
    const behind = -(px * ux + py * uy), across = Math.abs(px * uy - py * ux);

    return behind >= 0 && behind < 7 && across < 0.45 ? behind / 7 : -1;
}

export function heavens(x: number, y: number, cols: number, aspect: number, scene: Scene) {
    const unit = Math.max(1, scene.horizon) / 10;
    const cover = cloudCover(scene);
    if (cover > 0.02) {
        const u = ((x + (scene.yaw * cols * 0.8) / FIELD_OF_VIEW) * aspect + scene.time * WIND) / (unit * 3);
        const v = y / unit;
        const n = 0.65 * noise(u, v) + 0.35 * noise(u * 2.3 + 5, v * 2.3 + 3);
        // Thinner toward the horizon, so cloud sits up in the sky.
        const thick = n - (1 - cover * 0.75) + (1 - y / Math.max(1, scene.horizon)) * 0.1 - 0.1;
        if (thick > 0) {
            const tint = Math.min(3, Math.floor(thick * 20));

            return paint(density[ Math.min(5, 1 + Math.floor(thick * 30)) ]!, clouds[ y ]![ 3 ]!, tint > 1 ? clouds[ y ]![ tint - 2 ]! : sky[ y ]!);
        }
    }

    let back = sky[ y ]!, glyph = " ", ink = back;
    if (scene.aurora) {
        const glow = auroraAt(x, y, aspect, unit, scene.horizon, scene.time);
        const level = Math.min(AURORA_STEPS - 1, Math.floor(glow * AURORA_STEPS));
        if (level > 0) {
            back = auroraFill[ y ]![ auroraHue ]![ level ]!;
            ink = auroraInk[ y ]![ auroraHue ]![ level ]!;
            glyph = level > 3 ? "|" : level > 1 ? "\u00a6" : "'";
        }
    }

    const tail = meteorAt(x, y, aspect, cols, scene.horizon, scene.time);
    if (tail >= 0) return paint(tail < 0.15 ? "*" : tail < 0.5 ? "-" : "\u00b7", stars[ y ]![ tail < 0.5 ? 0 : 1 ]!, back);

    if (turn.time !== scene.time) {
        turn.time = scene.time;
        const angle = (scene.time / STAR_TURN) * Math.PI * 2;
        turn.cos = TRAIL.map((lag) => Math.cos(angle - lag));
        turn.sin = TRAIL.map((lag) => Math.sin(angle - lag));
    }

    const pole = scene.horizon * 0.4;
    const dx = (x + 0.5 - cols / 2) * aspect, dy = y + 0.5 + pole;
    for (let k = 0; k < TRAIL.length; k++) {
        const cos = turn.cos[ k ]!, sin = turn.sin[ k ]!;
        const gx = Math.floor((dx * cos - dy * sin) / aspect), gy = Math.floor(dx * sin + dy * cos);
        const h = hash(gx, gy);
        if (h <= 0.99) continue;

        // A rotated grid cell can straddle two screen cells; draw its star only in the one its centre lands in.
        const sx = (gx + 0.5) * aspect, sy = gy + 0.5;
        if (Math.floor((sx * cos + sy * sin) / aspect + cols / 2) !== x || Math.floor(-sx * sin + sy * cos - pole) !== y) continue;

        return k ? paint(k < 2 ? "\u00b7" : ".", stars[ y ]![ 1 ]!, back) : twinkle(h, scene.time, y, back);
    }

    return paint(glyph, ink, back);
}

export function shade(coord: Coord, context: Context, scene: Scene, tree: Overlay) {
    const {hole, horizon} = scene;
    if (coord.x >= hole.x && coord.x < hole.x + hole.w && coord.y >= hole.y && coord.y < hole.y + hole.h) {
        return " ";
    }

    if (bandsKey !== bandsFor(context.rows, horizon, scene)) buildBands(context.rows, horizon, scene);

    const back = coord.y >= horizon
        ? field(coord.x, coord.y, context.metrics.aspect, scene)
        : mountain(coord.x, coord.y, context.cols, scene) ?? heavens(coord.x, coord.y, context.cols, context.metrics.aspect, scene);

    if (tree.depth[ coord.index ]! < Infinity) {
        const light = tree.light[ coord.index ]!;
        const fill = fillAt(tree, coord.index);

        return lit(paint(tree.chars[ coord.index ]!, shadeColor(tree.colors[ coord.index ]!, light), fill ? shadeColor(fill, light) : back.backgroundColor, "bold"), tree.glow, coord.index);
    }

    return lit(back, tree.glow, coord.index);
}
