import {aimCamera} from "./camera";
import {drawFireworks} from "./fireworks";
import {drawGraves} from "./graves";
import {drawLeaves} from "./leaves";
import {drawPine, growPine, type Pine} from "./pine";
import type {Piece} from "./rasterize";
import {autumnAt, yearTime} from "./timeline";
import {drawWood, growTree, type Tree} from "./tree";

// The oak among the graves, turning through its seasons.
export const treePiece = (tree: Tree): Piece => ({
    draw: (overlay, view) => {
        const local = yearTime(view.time);
        const camera = aimCamera(view, view.yaw);
        drawGraves(overlay, view, view.yaw);
        drawWood(overlay, camera, tree);
        drawLeaves(overlay, camera, tree, local, autumnAt(local));
    },
});

// A decorated pine with gifts underneath, snowed in for the whole season.
export const pinePiece = (pine: Pine): Piece => ({
    draw  : (overlay, view) => drawPine(overlay, aimCamera(view, view.yaw), pine, view.time),
    winter: true,
    shadow: 0.55, // the pine is narrower than the oak's crown
    aurora: true,
    clouds: 0.45, // thin, so the aurora shows
});

const PIECES = {
    tree     : (seed: number) => treePiece(growTree(seed)),
    christmas: (seed: number) => pinePiece(growPine(seed)),
    newyear  : (seed: number) => {
        const pine = pinePiece(growPine(seed));

        return {...pine, draw: (overlay, view) => {
            pine.draw(overlay, view);
            drawFireworks(overlay, view);
        }} satisfies Piece;
    },
};

export type PieceName = keyof typeof PIECES;

// Month-day ranges, both ends included; a range may wrap past New Year. First match wins, so the last row is the rest of the year.
type Day = {
    from : string;
    to   : string;
    piece: PieceName;
};

export const CALENDAR: Day[] = [
    {from: "10-01", to: "11-02", piece: "tree"}, // Halloween
    {from: "12-26", to: "01-01", piece: "newyear"}, // the Christmas pine, with fireworks
    {from: "12-01", to: "01-31", piece: "christmas"},
    {from: "01-01", to: "12-31", piece: "tree"},
];

export function pieceFor(date: Date, calendar: Day[] = CALENDAR): PieceName {
    const today = `${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
    const row = calendar.find(({from, to}) => (from <= to ? from <= today && today <= to : today >= from || today <= to));

    return row ? row.piece : "tree";
}

// `?scene=` previews a piece out of season.
export const createPiece = (name: string | null, date: Date, seed: number) => PIECES[ name && name in PIECES ? (name as PieceName) : pieceFor(date) ](seed);
